SELECT 'invalid_transfer_decisions',COUNT(*) FROM student_class_transfer_event WHERE from_class_id=to_class_id OR revision_before<0 OR revision_after<>revision_before+1 OR applied_limit_months NOT BETWEEN 1 AND 120 OR reason NOT REGEXP '[^[:space:]]' OR request_hash NOT REGEXP '^[0-9A-F]{64}$' OR effective_date>DATE_ADD(source_course_start_date,INTERVAL applied_limit_months MONTH) OR effective_date>DATE_ADD(destination_course_start_date,INTERVAL applied_limit_months MONTH);
SELECT 'transfer_revision_gaps',COUNT(*) FROM (SELECT institution_id,student_id FROM student_class_transfer_event GROUP BY institution_id,student_id HAVING MIN(revision_after)<>1 OR MAX(revision_after)<>COUNT(*)) x;
SELECT 'transfer_trigger_inventory',ABS(4-COUNT(*)) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME IN ('transfer_event_insert','transfer_event_update','transfer_event_delete','student_transfer_revision_update');
SELECT 'transfer_restrict_fks',ABS(9-COUNT(*)) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='student_class_transfer_event' AND DELETE_RULE='RESTRICT' AND UPDATE_RULE='RESTRICT';
SELECT 'transfer_current_revision',COUNT(*) FROM student s LEFT JOIN (SELECT institution_id,student_id,MAX(revision_after) revision FROM student_class_transfer_event GROUP BY institution_id,student_id) e ON e.institution_id=s.institution_id AND e.student_id=s.id WHERE s.transfer_revision<>COALESCE(e.revision,0);
